import torch
from torch import Tensor

c = 1.0

def u(t: Tensor, x: Tensor, y: Tensor, z: Tensor) -> Tensor:
	r_sq = x**2+y**2+z**2

	E_x = torch.exp(-(10.*(r_sq)**(1/2)-10.*t-3.)**2)*x*z*(3+80000*x**2*y**2+80000*x**2*z**2+80000*y**2*z**2+40000*t**2*x**2+40000*t**2*y**2+40000*t**2*z**2+24000.0*t*x**2+24000.0*t*y**2+24000.0*t*z**2+40000*x**4+40000*y**4+40000*z**4+4000.00*x**2+4000.00*y**2+4000.00*z**2-180.0*(r_sq)**(1/2)-80000*(r_sq)**(1/2)*t*x**2-80000*(r_sq)**(1/2)*t*y**2-80000*z**2*(r_sq)**(1/2)*t-600*(r_sq)**(1/2)*t-24000.0*(r_sq)**(1/2)*x**2-24000.0*(r_sq)**(1/2)*y**2-24000.0*z**2*(r_sq)**(1/2))/(r_sq)**(5/2)
	E_y =  torch.exp(-(10.*(r_sq)**(1/2)-10.*t-3.)**2)*y*z*(3+80000*x**2*y**2+80000*x**2*z**2+80000*y**2*z**2+40000*t**2*x**2+40000*t**2*y**2+40000*t**2*z**2+24000.0*t*x**2+24000.0*t*y**2+24000.0*t*z**2+40000*x**4+40000*y**4+40000*z**4+4000.00*x**2+4000.00*y**2+4000.00*z**2-180.0*(r_sq)**(1/2)-80000*(r_sq)**(1/2)*t*x**2-80000*(r_sq)**(1/2)*t*y**2-80000*z**2*(r_sq)**(1/2)*t-600*(r_sq)**(1/2)*t-24000.0*(r_sq)**(1/2)*x**2-24000.0*(r_sq)**(1/2)*y**2-24000.0*z**2*(r_sq)**(1/2))/(r_sq)**(5/2)
	E_z =  -40000.00000*torch.exp(-(10.*(r_sq)**(1/2)-10.*t-3.)**2)*(((-.6000000000-2.000000000*t)*x**4+((-1.200000000-4.000000000*t)*y**2+(-.6000000000-2.000000000*t)*z**2-.5000000000e-2*t-.1500000000e-2)*x**2+(-.6000000000-2.000000000*t)*y**4+((-.6000000000-2.000000000*t)*z**2-.5000000000e-2*t-.1500000000e-2)*y**2+(.3000000000e-2+.1000000000e-1*t)*z**2)*(r_sq)**(1/2)+1.000000000*x**6+(3.000000000*y**2+2.000000000*z**2+(t+.3000000000)**2)*x**4+(3.000000000*y**4+(4.000000000*z**2+2.000000000*(t+.3000000000)**2)*y**2+.2500000000e-4+1.000000000*z**4+(t+.4000000000)*(t+.2000000000)*z**2)*x**2+1.000000000*y**6+(2.000000000*z**2+(t+.3000000000)**2)*y**4+(.2500000000e-4+1.000000000*z**4+(t+.4000000000)*(t+.2000000000)*z**2)*y**2-.5000000000e-4*z**2-.1000000000e-1*z**4)/(r_sq)**(5/2)
	B_x =  -20.*(2000.*(r_sq)**(1/2)*t**2+2000.*(r_sq)**(1/2)*x**2+2000.*(r_sq)**(1/2)*y**2+2000.*z**2*(r_sq)**(1/2)-4000.*t*x**2-4000.*t*y**2-4000.*t*z**2+1200.*(r_sq)**(1/2)*t-1200.*x**2-1200.*y**2-1200.*z**2+180.*(r_sq)**(1/2)-10.*t-3.)*y*torch.exp(-(10.*(r_sq)**(1/2)-10.*t-3.)**2)/(r_sq)**(3/2)
	B_y =  20.*(2000.*(r_sq)**(1/2)*t**2+2000.*(r_sq)**(1/2)*x**2+2000.*(r_sq)**(1/2)*y**2+2000.*z**2*(r_sq)**(1/2)-4000.*t*x**2-4000.*t*y**2-4000.*t*z**2+1200.*(r_sq)**(1/2)*t-1200.*x**2-1200.*y**2-1200.*z**2+180.*(r_sq)**(1/2)-10.*t-3.)*x*torch.exp(-(10.*(r_sq)**(1/2)-10.*t-3.)**2)/(r_sq)**(3/2)
	B_z =  torch.zeros(t.size()).to(t.device)

	return torch.vstack((E_x, E_y, E_z, B_x, B_y, B_z))